file.content:
.agent-panel {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: var(--color-bg-secondary);
}

.agent-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 24px;
  border-bottom: 1px solid var(--color-border-light);
  background: var(--color-bg-primary);
}

.agent-panel__title {
  font-size: 15px;
  font-weight: 700;
  color: var(--color-text-secondary);
}

.agent-panel__clear {
  height: 28px;
  width: 80px;
  padding: 0 10px;
  font-size: 12px;
  background: none;
  border: 1px solid var(--color-border-dark);
  border-radius: 6px;
  color: var(--color-text-subtle);
  cursor: pointer;
  box-sizing: border-box;
  text-align: center;
}

.agent-panel__clear:hover {
  background: var(--color-bg-code);
  color: var(--color-text-tertiary);
}

.agent-panel__actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.agent-panel__langfuse {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  height: 28px;
  width: 80px;
  padding: 0 10px;
  font-size: 12px;
  background: none;
  border: 1px solid var(--color-border-dark);
  border-radius: 6px;
  color: var(--color-text-subtle);
  cursor: pointer;
  box-sizing: border-box;
}

.agent-panel__langfuse-icon {
  width: 14px;
  height: 14px;
}

.agent-panel__langfuse:hover:not(:disabled) {
  background: var(--color-bg-code);
  color: var(--color-text-tertiary);
}

.agent-panel__langfuse--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.agent-panel__messages {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
}

.agent-panel__empty {
  text-align: center;
  color: var(--color-text-disabled);
  font-size: 14px;
  margin-top: 40px;
  padding: 0 20px;
  line-height: 1.5;
}

