.sidebar {
  background: var(--color-bg-tertiary);
  border-right: 1px solid var(--color-border-medium);
  padding: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  height: 100vh;
}

.sidebar--collapsed {
  border-right: 1px solid var(--color-border-medium);
  width: 44px;
  min-width: 44px;
}

.sidebar__top {
  flex-shrink: 0;
  background: var(--color-bg-tertiary);
  border-bottom: 1px solid var(--color-border-medium);
  position: sticky;
  top: 0;
  z-index: 1;
}

.sidebar__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
}

.sidebar--collapsed .sidebar__top {
  border-bottom: none;
}

.sidebar--collapsed .sidebar__header {
  justify-content: center;
  padding: 12px 8px;
}

.sidebar__actions {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 0 8px;
}

.sidebar__action-btn {
  background: none;
  border: 1px solid var(--color-border-medium);
  cursor: pointer;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  color: var(--color-text-muted);
  transition: background 0.15s, color 0.15s;
}

.sidebar__action-btn:hover {
  background: var(--color-bg-hover-strong);
  color: var(--color-text-primary);
}

.sidebar__action-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.sidebar__action-btn--danger:hover:not(:disabled) {
  background: var(--color-error-bg-subtle);
  color: var(--color-error);
}

.sidebar__action-btn--active {
  background: var(--color-accent-primary);
  color: #fff;
  border-color: var(--color-accent-primary);
}

.sidebar__action-btn--active:hover {
  background: var(--color-accent-primary-hover);
  color: #fff;
}

.sidebar__search-input {
  width: 100%;
  box-sizing: border-box;
  padding: 6px 10px;
  font-size: 13px;
  border: 1px solid var(--color-border-medium);
  border-radius: 6px;
  background: var(--color-bg-primary);
  color: var(--color-text-primary);
  margin-bottom: 8px;
  outline: none;
}

.sidebar__search-input:focus {
  border-color: var(--color-accent-primary);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.15);
}

.sidebar__title {
  margin: 0;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--color-text-muted);
}

.sidebar--collapsed .sidebar__title {
  display: none;
}

.sidebar__content {
  flex: 1 1 0;
  min-height: 0;
  overflow-y: auto;
  padding: 12px 16px;
}

.sidebar--collapsed .sidebar__content {
  display: none;
}

.sidebar__conversations {
  flex: 1.5;
  min-height: 0;
  border-top: 1px solid var(--color-border-medium);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.sidebar--collapsed .sidebar__conversations {
  display: none;
}

.sidebar__collapse-toggle {
  background: none;
  border: none;
  cursor: pointer;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  flex-shrink: 0;
}

.sidebar__collapse-toggle:hover {
  background: var(--color-bg-hover-strong);
}

.sidebar__hamburger {
  display: block;
  width: 16px;
  height: 2px;
  background: var(--color-text-muted);
  position: relative;
}

.sidebar__hamburger::before,
.sidebar__hamburger::after {
  content: '';
  display: block;
  width: 16px;
  height: 2px;
  background: var(--color-text-muted);
  position: absolute;
  left: 0;
}

.sidebar__hamburger::before {
  top: -5px;
}

.sidebar__hamburger::after {
  top: 5px;
}

.sidebar__empty {
  font-size: 13px;
  color: var(--color-text-faint);
}

.sidebar__list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.sidebar__item {
  margin-bottom: 4px;
}

.sidebar__table-header {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}

.sidebar__toggle {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 10px;
  padding: 2px 4px;
  color: var(--color-text-muted);
}

.sidebar__table-name {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-primary);
  padding: 2px 4px;
  border-radius: 3px;
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  flex: 1;
}

.sidebar__table-name:hover {
  background: var(--color-bg-hover-strong);
}

.sidebar__row-count {
  font-size: 11px;
  color: var(--color-text-faint);
  margin-left: auto;
}

.sidebar__delete {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--color-text-muted);
  padding: 0 2px;
  flex-shrink: 0;
  opacity: 1;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

.sidebar__delete:hover {
  color: var(--color-error);
}

@media (pointer: coarse) {
  .sidebar__delete {
    min-width: 36px;
    min-height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
  }
}

.sidebar__columns {
  list-style: none;
  padding: 4px 0 4px 24px;
  margin: 0;
}

.sidebar__column {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  padding: 2px 0;
}

.sidebar__col-name {
  color: var(--color-text-primary);
}

.sidebar__col-type {
  color: var(--color-text-faint);
  font-style: italic;
}

.sidebar__footer {
  flex-shrink: 0;
  border-top: 1px solid var(--color-border-medium);
  padding: 8px 16px;
  display: flex;
  align-items: center;
}

.sidebar--collapsed .sidebar__footer {
  justify-content: center;
  padding: 8px;
}

.sidebar__github-link {
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
  text-decoration: none;
  border-radius: 4px;
  padding: 4px;
  transition: color 0.15s, background 0.15s;
}

.sidebar__github-link:hover {
  color: var(--color-text-primary);
  background: var(--color-bg-hover-strong);
}

.sidebar__tabs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  flex: 1;
}

.sidebar__tab {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--color-text-muted);
  padding: 4px 8px;
  border-bottom: 2px solid transparent;
  transition: color 0.15s, border-color 0.15s;
  text-align: center;
  width: 100%;
}

.sidebar__tab--active {
  color: var(--color-accent-primary);
  border-bottom-color: var(--color-accent-primary);
}

.sidebar__tab:hover:not(.sidebar__tab--active) {
  color: var(--color-text-primary);
}

.sidebar--collapsed .sidebar__tabs {
  display: none;
}

